<script lang="ts">import{invalidateAll,goto}from'$app/navigation';import type{TargetedAcquisitionView}from'$lib/types/pipe4';let{data}=$props();let busy=$state<string|null>(null);let error=$state<string|null>(null);async function respond(row:TargetedAcquisitionView,accept:boolean){busy=row.targeted_request_id;error=null;try{const action=accept?'accept':'decline';const r=await fetch(`/api/v1/pipe4/acquisition-requests/${row.targeted_request_id}/${action}`,{method:'POST'});if(!r.ok)throw new Error('Unable to update this request.');if(accept)await goto(`/report?targeted_request_id=${encodeURIComponent(row.targeted_request_id)}`);else await invalidateAll()}catch(e){error=e instanceof Error?e.message:'Request action failed'}finally{busy=null}}</script><div class="page"><header class="page-head"><div><h1>Nearby confirmation requests</h1><p>Accepting a request opens the same normal witness flow—there is no separate privileged verification path.</p></div></header>{#if data.error}<p class="error">{data.error}</p>{/if}{#if error}<p class="error">{error}</p>{/if}<div class="list">{#each data.rows as row}<article class="surface"><div class="row-between"><div><p class="eyebrow">Targeted acquisition</p><h2>{row.what_to_confirm??'Confirm current reality'}</h2>{#if row.identity}<p class="muted">{row.identity.entity_id} · {row.identity.state_type}</p>{/if}</div><span class="status">{row.status}</span></div>{#if row.reward_label}<p class="notice">Assigned reward: {row.reward_label}</p>{/if}{#if row.status==='OFFERED'}<div class="button-row"><button disabled={busy===row.targeted_request_id} onclick={()=>respond(row,true)}>Accept & report</button><button class="secondary" disabled={busy===row.targeted_request_id} onclick={()=>respond(row,false)}>Decline</button></div>{/if}</article>{:else}<div class="surface"><p class="muted">No confirmation requests are waiting for you.</p></div>{/each}</div></div>